    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    parent_id uuid,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    security_pin character varying(100),
    permissions text DEFAULT 'all'::text,
    whatsapp_enabled boolean DEFAULT true,
    CONSTRAINT users_role_check CHECK (((role)::text = ANY ((ARRAY['super_admin'::character varying, 'accountant'::character varying, 'distributor'::character varying, 'retailer'::character varying, 'operator'::character varying])::text[]))),
    CONSTRAINT users_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'suspended'::character varying, 'pending'::character varying])::text[])))
);


